import{z as s,x as d,o as E,c as m,q as o,j as B,D as t,d as r,s as i,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"对冲需求的来源","description":"","frontmatter":{"title":"对冲需求的来源","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/hedging-demand-origin.md","filePath":"econ/hedging-demand-origin.md","lastUpdated":1791063341000}'),A={name:"econ/hedging-demand-origin.md"};function p(C,a,h,z,g,D){const n=d("Mermaid");return E(),m("div",null,[a[2]||(a[2]=o('<h1 id="对冲需求的来源" tabindex="-1">对冲需求的来源 <a class="header-anchor" href="#对冲需求的来源" aria-label="Permalink to &quot;对冲需求的来源&quot;">​</a></h1><div class="epigraph"><p>$J$ 一旦依赖机会状态 $z$，最优暴露除切点外还要一项：$W$ 与 $z$ 在坏机会里同向还是反向，由 $J_{Wz}$ 的符号决定。</p><footer>—— Merton, An Intertemporal Capital Asset Pricing Model, Econometrica, 1973，组合需求一节</footer></div><p><a href="/econ/merton-portfolio-theory">上一课</a>在 \\(J(W)\\) 下得到纯切点。本课缺口是让投资机会随机：\\(r\\)、\\(\\mu\\)、\\(\\sigma\\) 或价格核随 \\(z\\) 变，\\(J=J(W,z)\\)。主干 ICAPM 已经把加总后的多 beta 写过；本课只补<strong>需求从哪一项来</strong>，不出清、不写截面。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(z\\) 的动力学 \\(\\mathrm{d}z=\\ldots\\) 与资产扩散相关。伊藤的交叉变差使 HJB 出现 \\(J_{Wz}\\)。对 \\(\\theta\\) 的一阶变成</p> \\[\\theta^\\ast=\\frac{\\mu-r}{\\gamma\\sigma^2}+\\theta^{\\text{hedge}}(J_{Wz},\\mathrm{Cov}(\\mathrm{d}S,\\mathrm{d}z)). \\]<p>切点项仍是「这瞬间的投机」；对冲项是「\\(z\\) 变差时我希望 \\(W\\) 在哪」。若某资产在机会恶化时上涨，厌恶机会风险的人额外买它，愿意接受更低的即时超额。缺口是把这句话留在需求层，不要立刻跳到「所以有三个因子」。</p><p><span class="marginnote">术语翻译：\\(J_{Wz}\\) 衡量「财富与投资机会是否互补」——机会变差时，多一笔钱能顶多大用。它决定你想让财富跟着机会同向走还是反向走，而资产与机会状态的协方差就是实现这件事的手柄。</span></p><p><span class="marginnote">机会恶化的定义依赖 \\(J\\)：利率下降对长期投资者是好是坏，看他是净债权人还是要再投资。符号不是普适的「买债券对冲」口号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>状态 \\((W,z)\\)，生成元含 \\(\\mathrm{d}W\\)、\\(\\mathrm{d}z\\)、\\(\\mathrm{d}\\langle W,z\\rangle\\)。对 \\(\\theta\\) 求导，投机项来自 \\(J_W\\) 对超额的暴露，对冲项来自 \\(J_{Wz}\\) 对交叉变差的暴露。CRRA 时相对对冲与财富无关，仍可能随 \\(z\\) 变。多个 \\(z\\) 就多个对冲基金——两基金变成 \\(k+2\\) 基金（Merton）。动态完备：若存在可交易资产能张成每个 \\(\\mathrm{d}z\\)，对冲可实施；否则个人留在未对冲的 \\(z\\) 风险里，那是不完全。</p>',11)),(E(),B(l,null,{default:t(()=>[i(n,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20J%5B%22J(W%2Cz)%22%5D%20--%3E%20FOC%5B%22%CE%B8%20%E7%9A%84%E4%B8%80%E9%98%B6%22%5D%0A%20%20FOC%20--%3E%20MY%5B%22%E5%88%87%E7%82%B9%3A%20(%CE%BC-r)%2F%CE%B3%CF%83%C2%B2%22%5D%0A%20%20FOC%20--%3E%20HD%5B%22%E5%AF%B9%E5%86%B2%3A%20J_Wz%20%E4%B8%8E%20Cov(S%2Cz)%22%5D%0A%20%20HD%20--%3E%20FND%5B%22k%2B2%20%E5%9F%BA%E9%87%91%2C%20%E5%B0%9A%E6%9C%AA%E5%87%BA%E6%B8%85%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与消费 CAPM：Breeden 说时间可分下这些对冲被 \\(c\\) 吸收。本课不吸收，故意把 \\(z\\) 留在需求里，好看见来源。两条路在完全市场可相容，主干已对照。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制是跨期保险。\\(z\\) 进入未来的可行集：再投资利率、风险价格、劳动收入机会。今天的组合是唯一能把财富在 \\(z\\) 的状态下搬家的工具（在给定菜单下）。\\(J_{Wz}\\gt 0\\) 表示财富与 \\(z\\) 互补（\\(z\\) 高时财富更值钱，或反之，取决于 \\(z\\) 的标号），于是要在 \\(\\mathrm{d}z\\) 上持有相应协方差。这与 Glosten–Milgrom 的保险不同：那边保的是不利选择，这边保的是投资机会。都叫对冲，对象不同。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：对冲资产像火灾保险——平时收益平平甚至嫌亏，但家里（投资机会）出事时它正好赔一笔。愿意年年付保费（接受更低的即时超额收益），换的是坏日子里财富不断档。")],-1)),(E(),B(l,null,{default:t(()=>[i(n,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22%E6%8A%95%E8%B5%84%E6%9C%BA%E4%BC%9A%20z%20%E6%81%B6%E5%8C%96%2C%20%E5%A6%82%E5%86%8D%E6%8A%95%E8%B5%84%E5%88%A9%E7%8E%87%E4%B8%8B%E9%99%8D%22%5D%20--%3E%20Q%7B%22%E6%89%8B%E9%87%8C%E6%9C%89%E5%9C%A8%20z%20%E6%81%B6%E5%8C%96%E6%97%B6%E4%B8%8A%E6%B6%A8%E7%9A%84%E8%B5%84%E4%BA%A7%3F%22%7D%0A%20%20Q%20--%20%22%E6%9C%89%22%20--%3E%20PAY%5B%22%E4%BB%8A%E5%A4%A9%E6%8E%A5%E5%8F%97%E8%BE%83%E4%BD%8E%E8%B6%85%E9%A2%9D%E6%94%B6%E7%9B%8A%2C%20%E7%9B%B8%E5%BD%93%E4%BA%8E%E4%BF%9D%E8%B4%B9%22%5D%0A%20%20Q%20--%20%22%E6%B2%A1%E6%9C%89%22%20--%3E%20HURT%5B%22%E8%B4%A2%E5%AF%8C%E4%B8%8E%E6%9C%BA%E4%BC%9A%E5%8F%8C%E8%BE%93%22%5D%0A%20%20PAY%20--%3E%20OK%5B%22%E5%9D%8F%E7%8A%B6%E6%80%81%E4%BB%8D%E6%9C%89%E8%B4%AD%E4%B9%B0%E5%8A%9B%2C%20%E6%B6%88%E8%B4%B9%E5%B9%B3%E6%BB%91%22%5D%0A%20%20HURT%20--%3E%20FIX%5B%22%E5%8F%AA%E8%83%BD%E5%89%8A%E5%87%8F%E6%B6%88%E8%B4%B9%2C%20%E6%88%96%E8%A2%AB%E8%BF%AB%E4%BD%8E%E5%8D%96%E9%AB%98%E4%B9%B0%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p>劳动收入若不可交易且与 \\(z\\) 相关，对冲项还要抵消人力资本的暴露——预算里本没有这项资产，需求在可交易菜单上找替代。不完全的典型来源。</p><p><span class="marginnote">随机机会把「长期投资者与短视投资者」分开。短视只看切点；长期多对冲。寿险与养老金的需求理论从这里起步，本课不展开产品。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要列举哪些宏观变量是 \\(z\\)。那是实施，滑向量化栏。下一课出清：人人带上对冲需求之后，若机会其实可由市场代表，连续时间 CAPM 仍可能只有一个 beta；一般则回到 ICAPM。本课不出清。</p><p><span class="marginnote">常见误区：「对冲就是多买债券」。方向取决于你站在哪：利率下降对靠利息再投资的长期者是坏机会，对净借款人反而松了口气。同一只资产，不同人的对冲需求可以方向相反。</span></p><p>后课默认：对冲需求来自 \\(J_{Wz}\\) 与资产–状态协方差，不是来自特质方差。切点项仍在。基金数目随独立 \\(z\\) 的可交易张成而定。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(J(W,z)\\) 使最优 \\(\\theta\\) 含切点加对冲。</li><li>对冲保的是投资机会（及不可交易收入），符号由 \\(J_{Wz}\\) 决定。</li><li>本课是需求，不是定价方程，更不是因子表。</li><li>出处：Merton, <em>Econometrica</em> 1973（需求节）；对照 <em>JET</em> 1971 的常机会。</li></ul>',8))])}const u=s(A,[["render",p]]);export{c as __pageData,u as default};
